@import "@fontsource-variable/urbanist";
@import "@fontsource/lato/400.css";
@import "@fontsource/lato/400-italic.css";
@import "@fontsource/lato/700.css";
@import "@fontsource/lato/700-italic.css";

/* Light (faithful): the day half. White page, teal ink, cool grey-blue fog, a soft teal-tinted
   pill surface, seafoam/green for emphasis. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.31 0.053 195);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.31 0.053 195);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.31 0.053 195);
  --primary: oklch(0.67 0.16 157);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.96 0.012 170);
  --secondary-foreground: oklch(0.31 0.053 195);
  --muted: oklch(0.965 0.004 220);
  --muted-foreground: oklch(0.45 0.04 198);
  --accent: oklch(0.93 0.008 215);
  --accent-foreground: oklch(0.31 0.053 195);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.92 0.009 215);
  --input: oklch(0.88 0.013 215);
  --ring: oklch(0.67 0.16 157);
  --highlight: oklch(0.62 0.15 157);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.68 0.15 238);
  --chart-1: oklch(0.8 0.18 152);
  --chart-2: oklch(0.68 0.15 238);
  --chart-3: oklch(0.72 0.17 307);
  --chart-4: oklch(0.67 0.12 186);
  --chart-5: oklch(0.5 0.19 25);
  --sidebar: oklch(0.965 0.004 220);
  --sidebar-foreground: oklch(0.31 0.053 195);
  --sidebar-primary: oklch(0.67 0.16 157);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.93 0.008 215);
  --sidebar-accent-foreground: oklch(0.31 0.053 195);
  --sidebar-border: oklch(0.92 0.009 215);
  --sidebar-ring: oklch(0.67 0.16 157);

  --typeface-body: "Lato", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Urbanist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 90rem;
  --page-gutter: 1.25rem;
  --section-y: 4rem;
}

/* Dark: the night half. Pure black, deep teal panels, white text, seafoam highlights, an ocean
   teal for raised surfaces like the newsletter card. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.285 0.049 195);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.25 0.043 195);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.67 0.16 157);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.46 0.08 215);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.25 0.043 195);
  --muted-foreground: oklch(0.86 0.012 215 / 80%);
  --accent: oklch(0.4 0.045 195);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 16%);
  --input: oklch(1 0 0 / 22%);
  --ring: oklch(0.83 0.18 152);
  --highlight: oklch(0.83 0.18 152);
  --highlight-foreground: oklch(0.25 0.043 195);
  --glow: oklch(0.68 0.15 238);
  --chart-1: oklch(0.83 0.18 152);
  --chart-2: oklch(0.68 0.15 238);
  --chart-3: oklch(0.72 0.17 307);
  --chart-4: oklch(0.67 0.12 186);
  --chart-5: oklch(0.45 0.18 25);
  --sidebar: oklch(0.25 0.043 195);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.67 0.16 157);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.4 0.045 195);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 16%);
  --sidebar-ring: oklch(0.83 0.18 152);
}
